// Apollo.io on an API key: every operation in Apollo's REST API (people and company search and enrichment, contacts,
// accounts, deals, lists, sequences, outreach emails, tasks, calls, conversations, notes, fields, usage).
// actions.json is generated by `bun scripts/openapi-actions.ts apollo`. Apollo has no webhooks to subscribe to, so
// its triggers are polled (polls/apollo.ts).
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";

export const api: Api = {
  name: "Apollo.io",
  base: "https://api.apollo.io/api/v1",
  tokenHelp: "Apollo → Settings → Integrations → API → API keys",
  auth: (key) => ({ "x-api-key": key, "Cache-Control": "no-cache" }),
};

const get = (path: string) => ({ method: "GET", path, query: [], headers: [] });

const actions = await specActions(new URL("./actions.json", import.meta.url), api);
// a call that spends Apollo credits (enrichment, company search, job postings, news...) costs the business money, so it
// asks first even when it only reads; the generated description starts "<Summary>. Credits: ..." for those
for (const a of Object.values(actions)) if (a.description.includes(". Credits: ")) a.readOnly = false;

export const apollo: OwnApp = {
  app: "apollo",
  name: "Apollo.io",
  logo: "/logos/apollo.svg",
  keyField: {
    label: "API key",
    help: "In Apollo, open Settings → Integrations → API → API keys, create a key and turn on \"Set as master key\" (a key limited to a few endpoints can't do most of what Emplio offers). Many calls (sequences, outreach emails, calls, deals, usage) need a paid Apollo plan, and enrichment and company search spend your Apollo credits.",
    placeholder: "Your Apollo API key",
  },
  // whose key it is; a key without the profile scope still connects if Apollo says it's logged in
  async check(key) {
    try {
      const u = (await call(api, key, get("/users/api_profile"), {})) as { first_name?: string; last_name?: string; name?: string; email?: string };
      return [u.first_name, u.last_name].filter(Boolean).join(" ") || u.name || u.email || "Apollo.io";
    } catch (e) {
      if (!(e instanceof AppsError) || e.expired) throw e;
      const h = (await call(api, key, get("/auth/health"), {})) as { is_logged_in?: boolean };
      if (!h.is_logged_in) throw new AppsError("Apollo.io didn't accept this API key; check it and paste it again");
      return "Apollo.io";
    }
  },
  actions: {
    ...actions,
    get_auth_status: rest(api, "GET", "/auth/health", "Checks that the connected Apollo API key works: is_logged_in true means it does.", z.object({})),
  },
};
